namespace UI_Desktop.Auth;

internal static class PasswordRecoveryWebViewHtmlBuilder
{
	public static string BuildDocument(bool rememberSessionByDefault)
	{
		string text = (rememberSessionByDefault ? " checked" : string.Empty);
		return "<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n<head>\r\n    <meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\r\n    <title>Khôi phục mật khẩu NestG</title>\r\n    <style>\r\n        :root {\r\n            color-scheme: dark;\r\n            --bg: #070d14;\r\n            --panel: #101a26;\r\n            --line: #203044;\r\n            --text: #f2f7ff;\r\n            --muted: #8fa0b6;\r\n            --cyan: #27d9ff;\r\n            --blue: #289bed;\r\n            --green: #9bd33d;\r\n        }\r\n\r\n        * { box-sizing: border-box; }\r\n        html, body { width: 100%; min-height: 100%; margin: 0; }\r\n        body {\r\n            min-width: 0;\n            overflow: hidden;\r\n            background:\r\n                radial-gradient(circle at 25% 34%, rgba(39, 153, 220, .18), transparent 28%),\r\n                radial-gradient(circle at 70% 108%, rgba(80, 153, 44, .12), transparent 30%),\r\n                linear-gradient(145deg, #0b131e 0%, #060b11 72%);\r\n            color: var(--text);\r\n            font-family: \"Segoe UI Variable Text\", \"Segoe UI\", Arial, sans-serif;\r\n        }\r\n\r\n        button, input { font: inherit; }\r\n        button { color: inherit; }\r\n        [hidden] { display: none !important; }\r\n\r\n        .app-shell {\r\n            min-height: 100vh;\r\n            display: grid;\r\n            grid-template-rows: 46px minmax(0, 1fr);\r\n        }\r\n\r\n        .titlebar {\r\n            position: relative;\r\n            z-index: 10;\r\n            display: grid;\r\n            grid-template-columns: minmax(0, 1fr) auto;\r\n            align-items: center;\r\n            border-bottom: 1px solid rgba(75, 95, 120, .24);\r\n            background: rgba(8, 12, 18, .94);\r\n            box-shadow: 0 12px 32px rgba(0, 0, 0, .24);\r\n        }\r\n\r\n        .brand {\r\n            height: 100%;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            min-width: 0;\r\n            padding-left: 16px;\r\n            color: #dbe8f5;\r\n            font-size: 12px;\r\n            font-weight: 850;\r\n            letter-spacing: .08em;\r\n            user-select: none;\r\n        }\r\n\r\n        .brand img {\r\n            width: 27px;\r\n            height: 27px;\r\n            object-fit: contain;\r\n            filter: drop-shadow(0 2px 5px rgba(0, 0, 0, .45));\r\n        }\r\n\r\n        .drag-region {\r\n            position: absolute;\r\n            inset: 0 116px 0 0;\r\n        }\r\n\r\n        .window-controls {\r\n            position: relative;\r\n            z-index: 2;\r\n            height: 100%;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 4px;\r\n            padding-right: 8px;\r\n        }\r\n\r\n        .window-button {\r\n            width: 32px;\r\n            height: 28px;\r\n            display: grid;\r\n            place-items: center;\r\n            border: 0;\r\n            border-radius: 4px;\r\n            background: transparent;\r\n            color: #cfd9e6;\r\n            cursor: pointer;\r\n            font-size: 13px;\r\n        }\r\n\r\n        .window-button:hover { background: rgba(255, 255, 255, .08); }\r\n        .window-button.is-close:hover { background: #c83232; color: #fff; }\r\n\r\n        .auth-stage {\r\n            min-height: 0;\r\n            display: grid;\r\n            grid-template-columns: minmax(300px, .92fr) minmax(410px, 1.08fr);\r\n            align-items: stretch;\r\n            padding: clamp(22px, 4vw, 58px);\r\n        }\r\n\r\n        .visual-panel {\r\n            position: relative;\r\n            min-height: 500px;\r\n            overflow: hidden;\r\n            display: flex;\r\n            flex-direction: column;\r\n            justify-content: flex-end;\r\n            padding: clamp(34px, 5vw, 72px);\r\n            border: 1px solid rgba(71, 125, 163, .26);\r\n            border-right: 0;\r\n            border-radius: 6px 0 0 6px;\r\n            background:\r\n                linear-gradient(180deg, rgba(4, 13, 21, .08), rgba(3, 10, 16, .88)),\r\n                linear-gradient(135deg, rgba(35, 126, 184, .28), rgba(8, 23, 35, .3) 56%, rgba(112, 161, 45, .12));\r\n            box-shadow: 0 26px 70px rgba(0, 0, 0, .32);\r\n        }\r\n\r\n        .visual-panel::before {\r\n            content: \"\";\r\n            position: absolute;\r\n            width: 440px;\r\n            height: 440px;\r\n            left: 50%;\r\n            top: 42%;\r\n            border: 1px solid rgba(102, 192, 244, .11);\r\n            transform: translate(-50%, -50%) rotate(45deg);\r\n            box-shadow:\r\n                0 0 0 62px rgba(102, 192, 244, .025),\r\n                0 0 0 124px rgba(102, 192, 244, .018);\r\n        }\r\n\r\n        .visual-logo {\r\n            position: absolute;\r\n            left: 50%;\r\n            top: 43%;\r\n            width: min(230px, 48%);\r\n            aspect-ratio: 1;\r\n            object-fit: contain;\r\n            opacity: .88;\r\n            transform: translate(-50%, -50%);\r\n            filter: drop-shadow(0 20px 35px rgba(0, 0, 0, .52));\r\n        }\r\n\r\n        .visual-copy {\r\n            position: relative;\r\n            z-index: 2;\r\n        }\r\n\r\n        .visual-copy span {\r\n            color: var(--cyan);\r\n            font-size: 11px;\r\n            font-weight: 900;\r\n            letter-spacing: .16em;\r\n        }\r\n\r\n        .visual-copy h1 {\r\n            max-width: 420px;\r\n            margin: 10px 0 0;\r\n            color: #f5f9fd;\r\n            font-size: clamp(26px, 3vw, 42px);\r\n            line-height: 1.08;\r\n            letter-spacing: -.03em;\r\n        }\r\n\r\n        .visual-copy p {\r\n            max-width: 400px;\r\n            margin: 16px 0 0;\r\n            color: #91a7bb;\r\n            font-size: 13px;\r\n            line-height: 1.6;\r\n        }\r\n\r\n        .recovery-panel {\r\n            min-height: 500px;\r\n            display: grid;\r\n            place-items: center;\r\n            padding: clamp(30px, 5vw, 76px);\r\n            border: 1px solid rgba(71, 125, 163, .26);\r\n            border-radius: 0 6px 6px 0;\r\n            background: linear-gradient(180deg, rgba(16, 31, 44, .98), rgba(8, 20, 30, .99));\r\n            box-shadow: 0 26px 70px rgba(0, 0, 0, .32);\r\n        }\r\n\r\n        .recovery-card {\r\n            width: min(430px, 100%);\r\n        }\r\n\r\n        .eyebrow {\r\n            color: #66c0f4;\r\n            font-size: 10px;\r\n            font-weight: 900;\r\n            letter-spacing: .15em;\r\n        }\r\n\r\n        .recovery-card h2 {\r\n            margin: 8px 0 5px;\r\n            color: #f4f8fc;\r\n            font-size: clamp(29px, 3vw, 39px);\r\n            line-height: 1.15;\r\n            letter-spacing: -.03em;\r\n        }\r\n\r\n        .subtitle {\r\n            margin: 0 0 24px;\r\n            color: var(--muted);\r\n            font-size: 13px;\r\n            line-height: 1.55;\r\n        }\r\n\r\n        .step-note {\r\n            display: flex;\r\n            gap: 10px;\r\n            align-items: flex-start;\r\n            margin: 0 0 18px;\r\n            padding: 13px 14px;\r\n            border: 1px solid rgba(102, 192, 244, .15);\r\n            border-radius: 5px;\r\n            background: rgba(102, 192, 244, .06);\r\n            color: #b7c9d8;\r\n            font-size: 12px;\r\n            line-height: 1.45;\r\n        }\r\n\r\n        .step-note strong { color: #dff5ff; }\r\n\r\n        .field {\r\n            display: grid;\r\n            gap: 8px;\r\n            margin-top: 16px;\r\n        }\r\n\r\n        .field label {\r\n            color: #aabcc9;\r\n            font-size: 11px;\r\n            font-weight: 800;\r\n            letter-spacing: .04em;\r\n            text-transform: uppercase;\r\n        }\r\n\r\n        .input-shell { position: relative; }\r\n\r\n        .input-shell input {\r\n            width: 100%;\r\n            height: 50px;\r\n            border: 1px solid rgba(86, 128, 160, .42);\r\n            border-radius: 4px;\r\n            outline: 0;\r\n            background: rgba(5, 17, 25, .82);\r\n            color: #eef6fc;\r\n            padding: 0 15px;\r\n            caret-color: var(--cyan);\r\n            transition: border-color .16s ease, background .16s ease, box-shadow .16s ease;\r\n        }\r\n\r\n        .input-shell input::placeholder { color: #62798a; }\r\n        .input-shell input:focus {\r\n            border-color: rgba(102, 192, 244, .82);\r\n            background: rgba(7, 22, 32, .98);\r\n            box-shadow: 0 0 0 3px rgba(102, 192, 244, .09);\r\n        }\r\n\r\n        .input-shell.has-action input { padding-right: 82px; }\r\n\r\n        .password-toggle {\r\n            position: absolute;\r\n            top: 50%;\r\n            right: 10px;\r\n            width: 58px;\r\n            height: 30px;\r\n            display: inline-flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            border: 1px solid rgba(102, 192, 244, .18);\r\n            border-radius: 999px;\r\n            background: rgba(102, 192, 244, .07);\r\n            color: #9fdfff;\r\n            cursor: pointer;\r\n            font-size: 11px;\r\n            font-weight: 850;\r\n            letter-spacing: .02em;\r\n            transform: translateY(-50%);\r\n            transition: border-color .16s ease, background .16s ease, color .16s ease, box-shadow .16s ease;\r\n        }\r\n\r\n        .password-toggle:hover,\r\n        .password-toggle:focus-visible {\r\n            border-color: rgba(102, 192, 244, .48);\r\n            background: rgba(102, 192, 244, .14);\r\n            color: #dcf6ff;\r\n            box-shadow: 0 0 0 3px rgba(102, 192, 244, .08);\r\n            outline: 0;\r\n        }\r\n\r\n        .form-options {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: space-between;\r\n            gap: 18px;\r\n            margin-top: 18px;\r\n            color: #9eb0bf;\r\n            font-size: 12px;\r\n        }\r\n\r\n        .remember {\r\n            display: inline-flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n            cursor: pointer;\r\n            user-select: none;\r\n        }\r\n\r\n        .remember input {\r\n            width: 16px;\r\n            height: 16px;\r\n            margin: 0;\r\n            accent-color: var(--blue);\r\n        }\r\n\r\n        .link-button {\r\n            padding: 0;\r\n            border: 0;\r\n            background: transparent;\r\n            color: #8fd4ff;\r\n            cursor: pointer;\r\n            font-size: 12px;\r\n            font-weight: 750;\r\n        }\r\n\r\n        .link-button:hover,\r\n        .link-button:focus-visible {\r\n            color: #c4efff;\r\n            text-decoration: underline;\r\n            outline: 0;\r\n        }\r\n\r\n        .link-button:disabled {\r\n            cursor: wait;\r\n            opacity: .55;\r\n            text-decoration: none;\r\n        }\r\n\r\n        .status {\r\n            min-height: 20px;\r\n            margin: 15px 0 0;\r\n            color: #91c8e8;\r\n            font-size: 12px;\r\n            line-height: 1.45;\r\n        }\r\n\r\n        .status.is-error { color: #ff9d9d; }\r\n        .status.is-success { color: #bdf18a; }\r\n\r\n        .submit-button {\r\n            width: 100%;\r\n            min-height: 50px;\r\n            margin-top: 9px;\r\n            border: 1px solid rgba(190, 240, 111, .24);\r\n            border-radius: 4px;\r\n            background: linear-gradient(180deg, #9bd33d 0%, #75a920 100%);\r\n            color: #fff;\r\n            cursor: pointer;\r\n            font-size: 13px;\r\n            font-weight: 900;\r\n            box-shadow:\r\n                inset 0 1px 0 rgba(255, 255, 255, .14),\r\n                0 10px 24px rgba(89, 132, 28, .18);\r\n            transition: filter .16s ease, transform .16s ease, opacity .16s ease;\r\n        }\r\n\r\n        .submit-button:hover,\r\n        .submit-button:focus-visible {\r\n            filter: brightness(1.08);\r\n            transform: translateY(-1px);\r\n            outline: 0;\r\n        }\r\n\r\n        .submit-button:disabled {\r\n            cursor: wait;\r\n            opacity: .68;\r\n            transform: none;\r\n        }\r\n\r\n        .login-row {\r\n            margin: 22px 0 0;\r\n            color: #7f93a4;\r\n            text-align: center;\r\n            font-size: 12px;\r\n        }\r\n\r\n        .login-row .link-button { margin-left: 5px; }\r\n\r\n        @media (max-width: 920px) {\r\n            .auth-stage {\r\n                grid-template-columns: 1fr;\r\n                padding: 24px;\r\n            }\r\n\r\n            .visual-panel { display: none; }\r\n            .recovery-panel {\r\n                min-height: calc(100vh - 94px);\r\n                border-radius: 6px;\r\n            }\r\n        }\r\n\r\n        @media (max-height: 720px) {\r\n            body { overflow-y: auto; }\r\n            .auth-stage { padding-block: 20px; }\r\n            .visual-panel, .recovery-panel { min-height: 580px; }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"app-shell\">\r\n        <header class=\"titlebar\">\r\n            <div class=\"drag-region\" data-drag-region></div>\r\n            <div class=\"brand\">\r\n                <img src=\"https://nestg-assets.local/logo.png\" alt=\"\" />\r\n                <span>NESTG LAUNCHER</span>\r\n            </div>\r\n            <div class=\"window-controls\">\r\n                <button type=\"button\" class=\"window-button\" data-action=\"minimize\" aria-label=\"Thu nhỏ\">−</button>\r\n                <button type=\"button\" class=\"window-button\" data-action=\"maximize\" aria-label=\"Phóng to\">□</button>\r\n                <button type=\"button\" class=\"window-button is-close\" data-action=\"close\" aria-label=\"Đóng\">×</button>\r\n            </div>\r\n        </header>\r\n\r\n        <main class=\"auth-stage\">\r\n            <section class=\"visual-panel\" aria-hidden=\"true\">\r\n                <img class=\"visual-logo\" src=\"https://nestg-assets.local/logo.png\" alt=\"\" />\r\n                <div class=\"visual-copy\">\r\n                    <span>NESTG SECURITY</span>\r\n                    <h1>Lấy lại quyền truy cập tài khoản.</h1>\r\n                    <p>NestG sẽ gửi OTP đến email đã xác thực để bạn đặt lại mật khẩu an toàn.</p>\r\n                </div>\r\n            </section>\r\n\r\n            <section class=\"recovery-panel\">\r\n                <form class=\"recovery-card\" data-recovery-form novalidate>\r\n                    <span class=\"eyebrow\">BẢO MẬT TÀI KHOẢN</span>\r\n                    <h2 data-title>Quên mật khẩu</h2>\r\n                    <p class=\"subtitle\" data-subtitle>Nhập email tài khoản để nhận mã OTP đặt lại mật khẩu.</p>\r\n\r\n                    <div data-email-step>\r\n                        <div class=\"field\">\r\n                            <label for=\"email\">Email</label>\r\n                            <div class=\"input-shell\">\r\n                                <input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"username\" placeholder=\"you@example.com\" required />\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div data-reset-step hidden>\r\n                        <div class=\"step-note\">\r\n                            <span>●</span>\r\n                            <span>\r\n                                <strong data-challenge-email></strong><br />\r\n                                <span data-challenge-message></span><br />\r\n                                <small data-challenge-expiry></small>\r\n                            </span>\r\n                        </div>\r\n\r\n                        <div class=\"field\">\r\n                            <label for=\"otp\">Mã OTP</label>\r\n                            <div class=\"input-shell\">\r\n                                <input id=\"otp\" name=\"otp\" type=\"text\" inputmode=\"numeric\" autocomplete=\"one-time-code\" maxlength=\"12\" placeholder=\"Nhập mã OTP từ email\" />\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"field\">\r\n                            <label for=\"password\">Mật khẩu mới</label>\r\n                            <div class=\"input-shell has-action\">\r\n                                <input id=\"password\" name=\"password\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Ít nhất 6 ký tự\" />\r\n                                <button type=\"button\" class=\"password-toggle\" data-password-toggle=\"password\">Hiện</button>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"field\">\r\n                            <label for=\"confirmPassword\">Xác nhận mật khẩu</label>\r\n                            <div class=\"input-shell has-action\">\r\n                                <input id=\"confirmPassword\" name=\"confirmPassword\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Nhập lại mật khẩu mới\" />\r\n                                <button type=\"button\" class=\"password-toggle\" data-password-toggle=\"confirmPassword\">Hiện</button>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"form-options\">\r\n                        <label class=\"remember\">\r\n                            <input name=\"remember\" type=\"checkbox\"" + text + " />\r\n                            <span>Ghi nhớ sau khi đặt lại</span>\r\n                        </label>\r\n                        <button type=\"button\" class=\"link-button\" data-action=\"resendOtp\" data-resend-button hidden>Gửi lại OTP</button>\r\n                    </div>\r\n\r\n                    <p class=\"status\" data-status aria-live=\"polite\"></p>\r\n                    <button type=\"submit\" class=\"submit-button\" data-submit>Gửi mã OTP</button>\r\n\r\n                    <p class=\"login-row\">\r\n                        Đã nhớ mật khẩu?\r\n                        <button type=\"button\" class=\"link-button\" data-action=\"login\">Đăng nhập</button>\r\n                    </p>\r\n                </form>\r\n            </section>\r\n        </main>\r\n    </div>\r\n\r\n    <script>\r\n        (() => {\r\n            const post = message => window.chrome?.webview?.postMessage(message);\r\n            const form = document.querySelector('[data-recovery-form]');\r\n            const emailStep = document.querySelector('[data-email-step]');\r\n            const resetStep = document.querySelector('[data-reset-step]');\r\n            const emailInput = form?.elements.namedItem('email');\r\n            const otpInput = form?.elements.namedItem('otp');\r\n            const passwordInput = form?.elements.namedItem('password');\r\n            const confirmPasswordInput = form?.elements.namedItem('confirmPassword');\r\n            const rememberInput = form?.elements.namedItem('remember');\r\n            const submitButton = document.querySelector('[data-submit]');\r\n            const resendButton = document.querySelector('[data-resend-button]');\r\n            const status = document.querySelector('[data-status]');\r\n            const title = document.querySelector('[data-title]');\r\n            const subtitle = document.querySelector('[data-subtitle]');\r\n            const challengeEmail = document.querySelector('[data-challenge-email]');\r\n            const challengeMessage = document.querySelector('[data-challenge-message]');\r\n            const challengeExpiry = document.querySelector('[data-challenge-expiry]');\r\n            const secondaryActions = document.querySelectorAll('[data-action=\"login\"], [data-action=\"resendOtp\"]');\r\n            let resetMode = false;\r\n            let activeEmail = '';\r\n\r\n            function setStatus(message = '', isError = false, isSuccess = false) {\r\n                if (!status) return;\r\n                status.textContent = message;\r\n                status.classList.toggle('is-error', Boolean(isError));\r\n                status.classList.toggle('is-success', Boolean(isSuccess) && !isError);\r\n            }\r\n\r\n            function setState(isBusy, message = '', isError = false, isSuccess = false) {\r\n                if (submitButton) {\r\n                    submitButton.disabled = isBusy;\r\n                    submitButton.textContent = isBusy\r\n                        ? resetMode ? 'Đang đặt lại...' : 'Đang gửi OTP...'\r\n                        : resetMode ? 'Đặt lại mật khẩu' : 'Gửi mã OTP';\r\n                }\r\n\r\n                [emailInput, otpInput, passwordInput, confirmPasswordInput, rememberInput]\r\n                    .forEach(input => {\r\n                        if (input) input.disabled = isBusy;\r\n                    });\r\n                secondaryActions.forEach(button => button.disabled = isBusy);\r\n                document.querySelectorAll('[data-password-toggle]').forEach(button => button.disabled = isBusy);\r\n                setStatus(message, isError, isSuccess);\r\n            }\r\n\r\n            function setChallenge(challenge) {\r\n                resetMode = true;\r\n                activeEmail = String(challenge?.email || emailInput?.value || '').trim();\r\n\r\n                if (emailStep) emailStep.hidden = true;\r\n                if (resetStep) resetStep.hidden = false;\r\n                if (resendButton) resendButton.hidden = false;\r\n                if (title) title.textContent = 'Đặt lại mật khẩu';\r\n                if (subtitle) subtitle.textContent = 'Nhập OTP trong email và mật khẩu mới của bạn.';\r\n                if (challengeEmail) challengeEmail.textContent = activeEmail;\r\n                if (challengeMessage) challengeMessage.textContent = challenge?.message || 'OTP đã được gửi đến email của bạn.';\r\n                if (challengeExpiry) challengeExpiry.textContent = challenge?.expiresAtText || '';\r\n                setState(false, challenge?.message || 'OTP đã được gửi. Vui lòng kiểm tra email.', false, true);\r\n                window.requestAnimationFrame(() => otpInput?.focus());\r\n            }\r\n\r\n            window.__nestgRecovery = {\r\n                setState,\r\n                setChallenge,\r\n                focus() {\r\n                    (resetMode ? otpInput : emailInput)?.focus();\r\n                }\r\n            };\r\n\r\n            form?.addEventListener('submit', event => {\r\n                event.preventDefault();\r\n\r\n                if (!resetMode) {\r\n                    const email = String(emailInput?.value || '').trim();\r\n                    if (!email) {\r\n                        setState(false, 'Vui lòng nhập email để nhận OTP.', true);\r\n                        emailInput?.focus();\r\n                        return;\r\n                    }\r\n\r\n                    setState(true);\r\n                    post({\r\n                        type: 'forgotPassword',\r\n                        email\r\n                    });\r\n                    return;\r\n                }\r\n\r\n                const otp = String(otpInput?.value || '').trim();\r\n                const password = String(passwordInput?.value || '');\r\n                const confirmPassword = String(confirmPasswordInput?.value || '');\r\n\r\n                if (!otp || !password || !confirmPassword) {\r\n                    setState(false, 'Vui lòng nhập đầy đủ OTP và mật khẩu mới.', true);\r\n                    (!otp ? otpInput : !password ? passwordInput : confirmPasswordInput)?.focus();\r\n                    return;\r\n                }\r\n\r\n                if (password.length < 6) {\r\n                    setState(false, 'Mật khẩu mới phải có ít nhất 6 ký tự.', true);\r\n                    passwordInput?.focus();\r\n                    return;\r\n                }\r\n\r\n                if (password !== confirmPassword) {\r\n                    setState(false, 'Mật khẩu xác nhận chưa khớp.', true);\r\n                    confirmPasswordInput?.focus();\r\n                    return;\r\n                }\r\n\r\n                setState(true);\r\n                post({\r\n                    type: 'resetPassword',\r\n                    email: activeEmail,\r\n                    otp,\r\n                    password,\r\n                    remember: Boolean(rememberInput?.checked)\r\n                });\r\n            });\r\n\r\n            document.querySelectorAll('[data-password-toggle]').forEach(button => {\r\n                button.addEventListener('click', () => {\r\n                    const targetName = button.getAttribute('data-password-toggle');\r\n                    const input = form?.elements.namedItem(targetName);\r\n                    if (!input) return;\r\n\r\n                    const showPassword = input.type === 'password';\r\n                    input.type = showPassword ? 'text' : 'password';\r\n                    button.textContent = showPassword ? 'Ẩn' : 'Hiện';\r\n                    input.focus();\r\n                });\r\n            });\r\n\r\n            document.addEventListener('pointerdown', event => {\r\n                const target = event.target instanceof Element ? event.target : null;\r\n                if (target?.closest('[data-drag-region]')) {\r\n                    post({ type: 'dragWindow' });\r\n                }\r\n            });\r\n\r\n            document.addEventListener('click', event => {\r\n                const target = event.target instanceof Element ? event.target.closest('[data-action]') : null;\r\n                if (!target) return;\r\n\r\n                const action = target.getAttribute('data-action');\r\n                if (action === 'resendOtp') {\r\n                    const email = activeEmail || String(emailInput?.value || '').trim();\r\n                    if (!email) {\r\n                        setState(false, 'Chưa có email để gửi lại OTP.', true);\r\n                        return;\r\n                    }\r\n\r\n                    setState(true);\r\n                    post({ type: 'resendOtp', email });\r\n                    return;\r\n                }\r\n\r\n                post({ type: action });\r\n            });\r\n\r\n            window.requestAnimationFrame(() => emailInput?.focus());\r\n        })();\r\n    </script>\r\n</body>\r\n</html>";
	}
